SELECT AVG(BMXWT) AS MeanBodyWeight
FROM survey
WHERE INDFMPIR BETWEEN 1.3 AND 2.5;

SELECT AVG(BMXBMI) AS MeanBMI
FROM survey
WHERE INDFMPIR < 1.3;

SELECT CAST(CAST(SUM(IIF(INDFMPIR >= 5, 1, 0)) AS REAL) * 100 / COUNT(*) AS DECIMAL(18,2)) AS MedianIncomeRatio
FROM survey
WHERE DMDEDUC2 < 3 AND INDFMPIR >= 5;

SELECT CAST(SUM(WTDRD1 * DR1TSUGR) AS REAL) / SUM(WTDRD野RD1) 
FROM survey 
WHERE INDFMPIR >= 2.5 AND INDFMPIR < 4.0;

SELECT AVG(CASE WHEN INDFMPIR >= 4 THEN RIDAGEYR END) / 10 AS MeanAgeYears
FROM survey
WHERE INDFMPIR >= 4 AND RIDAGEYR >= 18 AND RIDAGEYR <= 80;

SELECT CAST(CAST(SUM(WTDRD1 * DR1TCARB) AS REAL) / COUNT(DISTINCT SEQN) AS REAL) / 1000
FROM survey
WHERE DMDEDUC2 IN (4, 5, 7) AND WTDRD1 > 0;

